from mime import media_type
def select(header, handlers, fallback):
    kind = media_type(header)
    major = kind.split('/', 1)[0] + '/*'
    return handlers.get(kind, handlers.get(major, handlers.get('*/*', fallback)))
def decode(value, header, handlers, fallback):
    return select(header, handlers, fallback)(value)
